      "options": [
        {
          "include-filter": "android.car.apitest.PreInstalledPackagesTest"
        }
      ]
    },
    {
      "name": "SampleCustomInputServiceTest"
    },
    {
      "name": "vehicle_binding_integration_test"
    }
  ]
